jsonTools.init:
function init(eli) {
  if (!eli || !eli.storage || !eli.compat) return;

  var GH_OWNER = "apndrewn";
  var GH_REPO = "eli-data";
  var GH_BRANCH = "main";
  var BACKUP_SCHEMA_VERSION = 1;
  var STAT_KEYS = [
    { key: "totalActiveDays", label: "Days used",     icon: "📅" },
    { key: "docsReviewed",    label: "Docs reviewed", icon: "📄" },
    { key: "draftsCreated",   label: "Drafts built",  icon: "📝" },
    { key: "errorsFixed",     label: "Errors fixed",  icon: "🛡️" },
    { key: "risksFound",      label: "Risks found",   icon: "⚖️" },
    { key: "hoursSaved",      label: "Hours saved",   icon: "⏱️" },
    { key: "currentStreak",   label: "Current streak",icon: "🔥" },
  ];

  var _state = {
    userKey: "",       // where telemetry was fetched from (source of truth)
    targetKey: "",     // where restore gets pushed (may differ if user has a new key)
    trophyCatalog: [],
    loadedDigest: null,
    reconstructed: null,
    trophySelection: {},
    statInputs: {},
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // userKeys / filenames on eli-data live LOWERCASE (e.g. `jl-4scjk8n4.json`).
  // GitHub's Contents API is case-sensitive, so any uppercase input returns
  // 404 even if the underlying file exists. Normalize before every path use.
  function _normKey(k) {
    return String(k == null ? "" : k).trim().toLowerCase();
  }
  function _b64ToStr(b) {
    return decodeURIComponent(escape(atob(String(b || "").replace(/\s/g, ""))));
  }
  function _toast(msg, tone) {
    if (typeof showToast === "function") showToast(msg, tone || "info");
  }

  function _strToB64(s) {
    return btoa(unescape(encodeURIComponent(s)));
  }

  function _ghGetJson(path) {
    var pat = eli.compat.lsGet("eli_user_github_pat") || null;
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
      "/contents/" + encodeURIComponent(path) +
      "?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    var headers = {
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    };
    if (pat) headers["Authorization"] = "Bearer " + pat;
    return fetch(url, { cache: "no-store", headers: headers }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) {
        return r.text().then(function (t) {
          throw new Error("GET " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
        });
      }
      return r.json();
    }).then(function (meta) {
      if (!meta || !meta.content) return null;
      try { return JSON.parse(_b64ToStr(meta.content)); }
      catch (e) { throw new Error("Digest JSON parse failed: " + e.message); }
    });
  }

  // Get file's SHA (needed by GitHub Contents API for PUT-over-existing).
  function _ghGetSha(path) {
    var pat = eli.compat.lsGet("eli_user_github_pat") || null;
    if (!pat) return Promise.reject(new Error("Missing eli_user_github_pat"));
    var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
      "/contents/" + encodeURIComponent(path) +
      "?ref=" + encodeURIComponent(GH_BRANCH) + "&t=" + Date.now();
    return fetch(url, {
      cache: "no-store",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
    }).then(function (r) {
      if (r.status === 404) return null;
      if (!r.ok) return null;
      return r.json().then(function (j) { return (j && j.sha) || null; });
    }).catch(function () { return null; });
  }

  // PUT a JSON blob to the eli-data repo. Includes existing SHA when the
  // file already exists (GitHub's API requires it for updates).
  function _ghPutJson(path, obj, message) {
    var pat = eli.compat.lsGet("eli_user_github_pat") || null;
    if (!pat) return Promise.reject(new Error("No GitHub PAT in localStorage (eli_user_github_pat). Import your credentials first."));
    return _ghGetSha(path).then(function (existingSha) {
      var url = "https://api.github.com/repos/" + GH_OWNER + "/" + GH_REPO +
        "/contents/" + encodeURIComponent(path);
      var body = {
        message: message || ("Restore push " + new Date().toISOString()),
        content: _strToB64(JSON.stringify(obj, null, 2)),
        branch: GH_BRANCH,
      };
      if (existingSha) body.sha = existingSha;
      return fetch(url, {
        method: "PUT",
        headers: {
          "Authorization": "Bearer " + pat,
          "Accept": "application/vnd.github+json",
          "X-GitHub-Api-Version": "2022-11-28",
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
      }).then(function (r) {
        if (r.ok) return r.json();
        return r.text().then(function (t) {
          throw new Error("PUT " + path + ": HTTP " + r.status + " · " + t.slice(0, 200));
        });
      }).then(function (res) {
        // Fire-and-forget jsdelivr purge so the client isn't served a
        // stale cached copy on next fetch.
        var purge = "https://purge.jsdelivr.net/gh/" + GH_OWNER + "/" + GH_REPO +
          "@" + GH_BRANCH + "/" + path;
        fetch(purge, { method: "GET" }).catch(function () {});
        return res;
      });
    });
  }

  // Digest → { stats, trophyIds, source }. Prefers fleet.stats + fleet.trophyIds
  // (post-2026-06-30 format). Falls back to reducing days[] for legacy digests
  // where only fleet.trophies (a count) is present.
  function _reduceDigest(digest) {
    if (!digest) return null;
    var fleet = digest.fleet || {};
    if (fleet.stats && typeof fleet.stats === "object" && Array.isArray(fleet.trophyIds)) {
      return {
        stats: {
          totalActiveDays: Number(fleet.stats.totalActiveDays) || 0,
          docsReviewed:    Number(fleet.stats.docsReviewed) || 0,
          draftsCreated:   Number(fleet.stats.draftsCreated) || 0,
          errorsFixed:     Number(fleet.stats.errorsFixed) || 0,
          risksFound:      Number(fleet.stats.risksFound) || 0,
          hoursSaved:      Number(fleet.stats.hoursSaved) || 0,
          currentStreak:   Number(fleet.stats.currentStreak) || 0,
        },
        trophyIds: fleet.trophyIds.slice(),
        trophyDates: fleet.trophyDates || {},
        source: "digest-native",
      };
    }
    // Legacy path: reduce days[] into approximate stats. Trophy list not
    // available — only the count via fleet.trophies.
    var days = Array.isArray(digest.days) ? digest.days : [];
    var draftsTotal = 0;
    days.forEach(function (d) {
      var dr = d && d.drafts;
      if (dr && typeof dr.total === "number") draftsTotal += dr.total;
    });
    return {
      stats: {
        totalActiveDays: days.length,
        docsReviewed: 0,
        draftsCreated: draftsTotal,
        errorsFixed: 0,
        risksFound: 0,
        hoursSaved: 0,
        currentStreak: 0,
      },
      trophyIds: [],
      trophyDates: {},
      approximateTrophyCount: Number(fleet.trophies) || 0,
      source: "reconstructed",
    };
  }

  function _loadTrophyCatalog() {
    return eli.storage.getAll("trophies").then(function (rows) {
      _state.trophyCatalog = (rows || []).filter(function (t) { return t && t.id; });
      return _state.trophyCatalog;
    }).catch(function () { _state.trophyCatalog = []; return []; });
  }

  // Walk the trophy catalog and pull every unique `metric` referenced,
  // remembering the LARGEST target seen for each metric — the anchor for
  // the progress bars and the "how easy is this metric" ranking.
  function _collectTrophyMetrics(catalog) {
    var m = {};
    (catalog || []).forEach(function (t) {
      if (!t || !t.metric) return;
      var target = Number(t.target) || 0;
      if (!(t.metric in m) || target > m[t.metric]) m[t.metric] = target;
    });
    return m;
  }

  // Current progress for one trophy — returns { current, target, pct }.
  function _trophyProgress(t) {
    var current = Number(_state.statInputs[t.metric] || 0);
    var target = Math.max(1, Number(t.target) || 1);
    return {
      current: current,
      target: target,
      pct: Math.min(100, Math.max(0, (current / target) * 100)),
    };
  }

  function _buildBackupJson() {
    var unlocked = Object.keys(_state.trophySelection).filter(function (id) {
      return _state.trophySelection[id];
    });
    var unlockedDates = {};
    var now = Date.now();
    var inheritedDates = (_state.reconstructed && _state.reconstructed.trophyDates) || {};
    unlocked.forEach(function (id) {
      unlockedDates[id] = inheritedDates[id] || now;
    });
    var statsRow = {
      stat_id: "eli_user_stats",
      unlockedTrophies: unlocked,
      unlockedDates:    unlockedDates,
      count: 0,
      lastUpdated: now,
    };
    // Fold in every numeric input — headline stats + raw trophy metrics.
    Object.keys(_state.statInputs).forEach(function (k) {
      statsRow[k] = Number(_state.statInputs[k] || 0);
    });
    return {
      _backupSchemaVersion: BACKUP_SCHEMA_VERSION,
      _restoredBy: "admin_user_restore",
      _restoredFor: _state.userKey,
      _restoredAt: new Date().toISOString(),
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      exportedAt: new Date().toISOString(),
      idb: {
        stats: [statsRow],
        config: [],
      },
      localStorage: {},
    };
  }

  function _writeClipboard(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function () {
        return _fallbackCopy(text);
      });
    }
    return _fallbackCopy(text);
  }
  function _fallbackCopy(text) {
    return new Promise(function (resolve, reject) {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;left:-9999px;opacity:0;";
      document.body.appendChild(ta);
      ta.select();
      var ok = false;
      try { ok = document.execCommand("copy"); } catch (_e) {}
      document.body.removeChild(ta);
      ok ? resolve() : reject(new Error("clipboard blocked"));
    });
  }

  // ── Rendering ─────────────────────────────────────────────────────
  function _renderRoot() {
    return '' +
      '<div class="_aur_root">' +
        '<div class="_aur_header">' +
          '<div class="_aur_title">🔄 Admin User Restore</div>' +
          '<div class="_aur_subtitle">Rebuild stats + trophies for a wiped user, or stamp manual values</div>' +
        '</div>' +
        '<div class="_aur_body">' +
          _renderQuickClone() +
          _renderLookup() +
          '<div id="_aur_preview_slot"></div>' +
          '<div id="_aur_form_slot"></div>' +
          '<div id="_aur_export_slot"></div>' +
        '</div>' +
      '</div>';
  }

  function _renderQuickClone() {
    return '' +
      '<section class="_aur_card _aur_card_hero">' +
        '<div class="_aur_card_title">🧬 Quick clone — copy one user\'s state to another + bonus trophies</div>' +
        '<div class="_aur_hint">Fetches the source user\'s stats + trophies, aims them at the target, then awards N bonus easiest trophies on top. One click, ready to push.</div>' +
        '<div class="_aur_qc_grid">' +
          '<label class="_aur_fld">' +
            '<span class="_aur_fld_lbl">Source (copy FROM)</span>' +
            '<input id="_aur_qc_source" type="text" class="_aur_inp" placeholder="e.g. JL-4scjk8n4" />' +
          '</label>' +
          '<label class="_aur_fld">' +
            '<span class="_aur_fld_lbl">Target (apply TO)</span>' +
            '<input id="_aur_qc_target" type="text" class="_aur_inp" placeholder="e.g. AR-53sf0rbf" />' +
          '</label>' +
          '<label class="_aur_fld">' +
            '<span class="_aur_fld_lbl">Bonus trophies</span>' +
            '<input id="_aur_qc_bonus" type="number" min="0" class="_aur_inp _aur_inp_num" value="7" />' +
          '</label>' +
          '<button id="_aur_btn_qc" class="_aur_btn _aur_btn_primary _aur_qc_btn">🧬 Clone + bonus</button>' +
        '</div>' +
      '</section>';
  }

  function _renderLookup() {
    return '' +
      '<section class="_aur_card">' +
        '<div class="_aur_card_title">1 · Load user (source)</div>' +
        '<div class="_aur_row">' +
          '<label class="_aur_lbl">Source key</label>' +
          '<input id="_aur_input_userkey" type="text" class="_aur_inp" placeholder="e.g. ar-a83bcd7e" />' +
          '<button id="_aur_btn_load" class="_aur_btn _aur_btn_primary">Fetch telemetry</button>' +
          '<button id="_aur_btn_skip" class="_aur_btn _aur_btn_ghost">Skip — manual only</button>' +
        '</div>' +
        '<div class="_aur_hint">The <b>source key</b> is where the historical data lives. If the user was wiped and had to onboard again, this is the OLD key (from earlier telemetry files). The <b>target key</b> (where the restore gets pushed) is set separately in Section 4.</div>' +
      '</section>';
  }

  function _renderPreview(reduced) {
    if (!reduced) return '';
    var srcLabel = reduced.source === "digest-native"
      ? "loaded from digest (post-2026-06-30 format — lossless)"
      : "reconstructed from days[] (approximate — legacy digest format)";
    var trophyBit = reduced.source === "digest-native"
      ? _esc(String(reduced.trophyIds.length)) + " trophy id" + (reduced.trophyIds.length === 1 ? "" : "s") + " on file"
      : _esc(String(reduced.approximateTrophyCount || 0)) + " trophy count (IDs not preserved)";
    var statBits = STAT_KEYS.map(function (d) {
      return '<div class="_aur_stat_chip">' + d.icon + ' ' + _esc(d.label) + ': <b>' + _esc(String(reduced.stats[d.key] || 0)) + '</b></div>';
    }).join('');
    return '' +
      '<section class="_aur_card">' +
        '<div class="_aur_card_title">2 · What was found</div>' +
        '<div class="_aur_hint _aur_hint_src">Source: ' + srcLabel + '</div>' +
        '<div class="_aur_stat_grid">' + statBits + '</div>' +
        '<div class="_aur_trophy_bit">' + trophyBit + '</div>' +
      '</section>';
  }

  function _renderForm(reduced) {
    if (!reduced) return '';
    // Seed headline stats from telemetry (only if not already user-touched).
    STAT_KEYS.forEach(function (d) {
      if (_state.statInputs[d.key] == null) {
        _state.statInputs[d.key] = reduced.stats[d.key] || 0;
      }
    });
    // Seed every trophy-referenced metric to 0 unless already touched.
    var trophyMetrics = _collectTrophyMetrics(_state.trophyCatalog);
    Object.keys(trophyMetrics).forEach(function (m) {
      if (_state.statInputs[m] == null) _state.statInputs[m] = 0;
    });
    _state.trophySelection = {};
    (reduced.trophyIds || []).forEach(function (id) { _state.trophySelection[id] = true; });
    var headlineKeys = {};
    STAT_KEYS.forEach(function (d) { headlineKeys[d.key] = 1; });
    var statFields = STAT_KEYS.map(function (d) {
      return '' +
        '<label class="_aur_fld">' +
          '<span class="_aur_fld_lbl">' + d.icon + ' ' + _esc(d.label) + '</span>' +
          '<input data-stat="' + _esc(d.key) + '" type="number" min="0" class="_aur_inp _aur_inp_num" value="' + _esc(String(_state.statInputs[d.key])) + '" />' +
        '</label>';
    }).join('');
    // Metric inputs — every raw counter a trophy checks, minus the ones
    // already in the headline row. Editing these drives the progress bars.
    var metricFieldList = Object.keys(trophyMetrics).filter(function (k) {
      return !headlineKeys[k];
    }).sort();
    var metricFields = metricFieldList.map(function (m) {
      return '' +
        '<label class="_aur_fld">' +
          '<span class="_aur_fld_lbl">🎯 ' + _esc(m) + ' <span class="_aur_fld_hint">(max ' + trophyMetrics[m] + ')</span></span>' +
          '<input data-stat="' + _esc(m) + '" type="number" min="0" class="_aur_inp _aur_inp_num" value="' + _esc(String(_state.statInputs[m])) + '" />' +
        '</label>';
    }).join('');
    var trophyChecks = _state.trophyCatalog.map(function (t) {
      var checked = _state.trophySelection[t.id];
      var progress = _trophyProgress(t);
      var progressHtml = checked ? '' :
        '<div class="_aur_trophy_prog" title="' + _esc(t.metric || "") + ': ' + progress.current + ' / ' + progress.target + '">' +
          '<div class="_aur_trophy_prog_fill" style="width:' + progress.pct.toFixed(0) + '%;"></div>' +
        '</div>' +
        '<span class="_aur_trophy_prog_label">' + progress.current + ' / ' + progress.target + '</span>';
      return '' +
        '<label class="_aur_trophy_tile' + (checked ? ' _aur_trophy_on' : '') + '" data-trophy-tile="' + _esc(t.id) + '">' +
          '<input type="checkbox" class="_aur_trophy_cb" data-trophy="' + _esc(t.id) + '"' + (checked ? ' checked' : '') + ' />' +
          '<span class="_aur_trophy_icon">' + _esc(t.icon || "🏆") + '</span>' +
          '<span class="_aur_trophy_text">' +
            '<span class="_aur_trophy_title">' + _esc(t.title || t.id) + '</span>' +
            '<span class="_aur_trophy_id">' + _esc(t.id) + '</span>' +
            progressHtml +
          '</span>' +
        '</label>';
    }).join('');
    var trophyBar = '' +
      '<div class="_aur_trophy_bar">' +
        '<button class="_aur_btn _aur_btn_ghost" id="_aur_all_on">Select all</button>' +
        '<button class="_aur_btn _aur_btn_ghost" id="_aur_all_off">Clear all</button>' +
        '<input id="_aur_award_n" type="number" min="1" class="_aur_inp _aur_inp_num" style="max-width:70px;" placeholder="N" value="5" />' +
        '<button class="_aur_btn _aur_btn_ghost" id="_aur_btn_award_n" title="Auto-select the N unearned trophies with the smallest targets, and bump their metrics so the client sees consistent state">🎯 Award N easiest</button>' +
        '<span class="_aur_trophy_count" id="_aur_trophy_count"></span>' +
      '</div>';
    var metricSection = metricFields ? (
      '<div class="_aur_metric_head">Trophy metrics <span class="_aur_metric_sub">(raw counters — editing these updates every unearned trophy\'s progress bar)</span></div>' +
      '<div class="_aur_stat_form">' + metricFields + '</div>'
    ) : '';
    return '' +
      '<section class="_aur_card">' +
        '<div class="_aur_card_title">3 · Manual override</div>' +
        '<div class="_aur_hint">Edit any field. Trophies checked will unlock on import; unchecked ones will not. Progress bars show how close each unearned trophy is based on the metric values below.</div>' +
        '<div class="_aur_stat_form">' + statFields + '</div>' +
        metricSection +
        '<div class="_aur_trophy_head">Trophies (' + _state.trophyCatalog.length + ' available)</div>' +
        trophyBar +
        '<div class="_aur_trophy_grid">' + trophyChecks + '</div>' +
      '</section>';
  }

  function _renderExport() {
    var defaultTarget = _state.targetKey || _state.userKey || "";
    return '' +
      '<section class="_aur_card">' +
        '<div class="_aur_card_title">4 · Deliver the restore</div>' +
        '<div class="_aur_row">' +
          '<label class="_aur_lbl">Push to</label>' +
          '<input id="_aur_input_target" type="text" class="_aur_inp" placeholder="target userKey (their CURRENT key)" value="' + _esc(defaultTarget) + '" />' +
        '</div>' +
        '<div class="_aur_hint"><b>Push (recommended):</b> writes the backup to <code>restore/&lt;target key&gt;.json</code> on <code>eli-data</code>. The target user\'s client polls that path on every ELI boot and prompts them to apply. If the user was wiped and re-onboarded, use their NEW userKey here (find it in Admin Fleet — the row that just started reporting).</div>' +
        '<div class="_aur_export_row">' +
          '<button id="_aur_btn_push" class="_aur_btn _aur_btn_primary">🚀 Push to target key</button>' +
          '<button id="_aur_btn_copy" class="_aur_btn _aur_btn_ghost">📋 Copy JSON</button>' +
          '<button id="_aur_btn_download" class="_aur_btn _aur_btn_ghost">💾 Download</button>' +
        '</div>' +
        '<div class="_aur_hint">Fallback (if push fails): copy or download the JSON and send it to the user. They paste it into <b>Refresh ELI → Import Backup</b>.</div>' +
        '<pre id="_aur_export_preview" class="_aur_preview_pre"></pre>' +
      '</section>';
  }

  function _updateTrophyCount() {
    var n = 0;
    Object.keys(_state.trophySelection).forEach(function (k) { if (_state.trophySelection[k]) n++; });
    var el = document.getElementById("_aur_trophy_count");
    if (el) el.textContent = n + " selected";
  }

  function _mountEmptyForm() {
    _state.reconstructed = {
      stats: { totalActiveDays: 0, docsReviewed: 0, draftsCreated: 0, errorsFixed: 0, risksFound: 0, hoursSaved: 0, currentStreak: 0 },
      trophyIds: [], trophyDates: {}, source: "empty",
    };
    document.getElementById("_aur_preview_slot").innerHTML = _renderPreview(_state.reconstructed);
    document.getElementById("_aur_form_slot").innerHTML = _renderForm(_state.reconstructed);
    document.getElementById("_aur_export_slot").innerHTML = _renderExport();
    _wireForm();
    _wireExport();
    _updateTrophyCount();
  }

  function _wirePreview() {
    var input = document.getElementById("_aur_input_userkey");
    var btn = document.getElementById("_aur_btn_load");
    var skipBtn = document.getElementById("_aur_btn_skip");
    if (!input || !btn) return;
    if (skipBtn) {
      skipBtn.onclick = function () {
        _state.userKey = _normKey(input.value);
        _state.targetKey = _state.userKey;
        _loadTrophyCatalog().then(function () { _mountEmptyForm(); });
      };
    }
    btn.onclick = function () {
      var key = _normKey(input.value);
      if (!key) { _toast("Enter a source key first (or click Skip for manual-only)", "err"); return; }
      _state.userKey = key;
      _state.targetKey = key;  // default target to source; user can change in Section 4
      if (input) input.value = key; // reflect normalization back to the field
      btn.disabled = true;
      btn.textContent = "⏳ Fetching…";
      _loadTrophyCatalog()
        .then(function () { return _ghGetJson("usage/" + key + ".json"); })
        .then(function (digest) {
          if (!digest) {
            _toast("No telemetry file at usage/" + key + ".json — using manual-only mode", "warn");
            _state.loadedDigest = null;
            _state.reconstructed = {
              stats: { totalActiveDays: 0, docsReviewed: 0, draftsCreated: 0, errorsFixed: 0, risksFound: 0, hoursSaved: 0, currentStreak: 0 },
              trophyIds: [], trophyDates: {}, source: "empty",
            };
          } else {
            _state.loadedDigest = digest;
            _state.reconstructed = _reduceDigest(digest);
          }
          document.getElementById("_aur_preview_slot").innerHTML = _renderPreview(_state.reconstructed);
          document.getElementById("_aur_form_slot").innerHTML = _renderForm(_state.reconstructed);
          document.getElementById("_aur_export_slot").innerHTML = _renderExport();
          _wireForm();
          _wireExport();
          _updateTrophyCount();
        })
        .catch(function (err) {
          _toast("Fetch failed: " + (err && err.message || "unknown"), "err");
        })
        .then(function () {
          btn.disabled = false;
          btn.textContent = "Fetch telemetry";
        });
    };
  }

  // Update the progress bar + label inside each unearned trophy tile
  // in place. Cheap enough to run on every stat-input keystroke without
  // stealing focus from the number field the admin is typing into.
  function _refreshProgressBars() {
    var slot = document.getElementById("_aur_form_slot");
    if (!slot) return;
    var byId = {};
    _state.trophyCatalog.forEach(function (t) { byId[t.id] = t; });
    var tiles = slot.querySelectorAll("[data-trophy-tile]");
    for (var i = 0; i < tiles.length; i++) {
      var tile = tiles[i];
      var id = tile.getAttribute("data-trophy-tile");
      var t = byId[id];
      if (!t) continue;
      if (_state.trophySelection[id]) continue;   // earned — skip
      var progress = _trophyProgress(t);
      var fill = tile.querySelector("._aur_trophy_prog_fill");
      var label = tile.querySelector("._aur_trophy_prog_label");
      if (fill) fill.style.width = progress.pct.toFixed(0) + "%";
      if (label) label.textContent = progress.current + " / " + progress.target;
    }
  }

  function _awardNEasiest(n) {
    var count = Math.max(0, Number(n) || 0);
    if (!count) { _toast("Enter a positive number", "err"); return; }
    var unearned = _state.trophyCatalog.filter(function (t) {
      return !_state.trophySelection[t.id];
    }).sort(function (a, b) {
      var ta = Number(a.target) || 0;
      var tb = Number(b.target) || 0;
      if (ta !== tb) return ta - tb;
      return String(a.id).localeCompare(String(b.id));
    });
    var picked = unearned.slice(0, count);
    if (!picked.length) { _toast("Every trophy in the catalog is already selected", "warn"); return; }
    picked.forEach(function (t) {
      _state.trophySelection[t.id] = true;
      if (t.metric) {
        var current = Number(_state.statInputs[t.metric] || 0);
        var target = Number(t.target) || 0;
        if (current < target) _state.statInputs[t.metric] = target;
      }
    });
    // Full re-render — checkbox states + progress bars + metric inputs
    // all need to reflect the bumped values.
    document.getElementById("_aur_form_slot").innerHTML = _renderForm(_state.reconstructed);
    document.getElementById("_aur_export_slot").innerHTML = _renderExport();
    _wireForm();
    _wireExport();
    _updateTrophyCount();
    _toast("✅ Awarded " + picked.length + " easiest trophies + bumped their metrics", "ok");
  }

  function _wireForm() {
    var slot = document.getElementById("_aur_form_slot");
    if (!slot) return;
    slot.querySelectorAll("input[data-stat]").forEach(function (inp) {
      inp.oninput = function () {
        var k = inp.getAttribute("data-stat");
        _state.statInputs[k] = Math.max(0, Number(inp.value) || 0);
        _refreshProgressBars();
      };
    });
    slot.querySelectorAll("input[data-trophy]").forEach(function (cb) {
      cb.onchange = function () {
        var id = cb.getAttribute("data-trophy");
        _state.trophySelection[id] = !!cb.checked;
        var tile = slot.querySelector('[data-trophy-tile="' + id + '"]');
        if (tile) tile.classList.toggle("_aur_trophy_on", !!cb.checked);
        _updateTrophyCount();
      };
    });
    var allOn = document.getElementById("_aur_all_on");
    var allOff = document.getElementById("_aur_all_off");
    if (allOn) allOn.onclick = function () { _setAllTrophies(true); };
    if (allOff) allOff.onclick = function () { _setAllTrophies(false); };
    var awardBtn = document.getElementById("_aur_btn_award_n");
    var awardN = document.getElementById("_aur_award_n");
    if (awardBtn) awardBtn.onclick = function () {
      var n = awardN ? Number(awardN.value) : 0;
      _awardNEasiest(n);
    };
  }

  function _setAllTrophies(on) {
    _state.trophyCatalog.forEach(function (t) { _state.trophySelection[t.id] = !!on; });
    var slot = document.getElementById("_aur_form_slot");
    if (!slot) return;
    slot.querySelectorAll("input[data-trophy]").forEach(function (cb) {
      cb.checked = !!on;
      var id = cb.getAttribute("data-trophy");
      var tile = slot.querySelector('[data-trophy-tile="' + id + '"]');
      if (tile) tile.classList.toggle("_aur_trophy_on", !!on);
    });
    _updateTrophyCount();
  }

  function _wireExport() {
    var copyBtn = document.getElementById("_aur_btn_copy");
    var dlBtn = document.getElementById("_aur_btn_download");
    var pushBtn = document.getElementById("_aur_btn_push");
    var pre = document.getElementById("_aur_export_preview");
    var updatePreview = function () {
      if (!pre) return;
      var blob = _buildBackupJson();
      pre.textContent = JSON.stringify(blob, null, 2);
    };
    updatePreview();
    if (copyBtn) {
      copyBtn.onclick = function () {
        var json = JSON.stringify(_buildBackupJson(), null, 2);
        updatePreview();
        _writeClipboard(json).then(function () {
          _toast("✅ Backup copied · " + Math.round(json.length / 1024) + " KB. Paste into Refresh ELI → Import Backup on " + _state.userKey + "'s machine.", "ok");
        }).catch(function (err) {
          _toast("Copy failed: " + (err && err.message || "unknown") + ". Use Download instead.", "err");
        });
      };
    }
    if (dlBtn) {
      dlBtn.onclick = function () {
        var json = JSON.stringify(_buildBackupJson(), null, 2);
        updatePreview();
        try {
          var blobObj = new Blob([json], { type: "application/json" });
          var url = URL.createObjectURL(blobObj);
          var a = document.createElement("a");
          a.href = url;
          a.download = "eli-restore-" + _state.userKey + ".json";
          document.body.appendChild(a);
          a.click();
          document.body.removeChild(a);
          setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
          _toast("✅ Download started", "ok");
        } catch (e) {
          _toast("Download failed: " + (e && e.message || "unknown"), "err");
        }
      };
    }
    var targetInput = document.getElementById("_aur_input_target");
    if (targetInput) {
      targetInput.oninput = function () {
        _state.targetKey = _normKey(targetInput.value);
      };
    }
    if (pushBtn) {
      pushBtn.onclick = function () {
        var target = targetInput ? _normKey(targetInput.value) : "";
        if (!target) target = _normKey(_state.targetKey || _state.userKey);
        if (!target) { _toast("Enter a target userKey (the recipient's CURRENT key)", "err"); return; }
        _state.targetKey = target;
        if (targetInput) targetInput.value = target; // reflect normalization
        var backup = _buildBackupJson();
        // The receiving client will match on this to identify who the
        // restore is for; the source key is bookkeeping only.
        backup._restoredFor = target;
        var path = "restore/" + target + ".json";
        pushBtn.disabled = true;
        pushBtn.textContent = "⏳ Pushing…";
        _ghPutJson(path, backup, "Restore push for " + target + " (source: " + (_state.userKey || "manual") + ") — " + new Date().toISOString())
          .then(function () {
            _toast("✅ Pushed to " + path + ". " + target + " will get a confirm dialog on next ELI boot.", "ok");
          })
          .catch(function (err) {
            _toast("Push failed: " + (err && err.message || "unknown") + ". Use Copy / Download as fallback.", "err");
          })
          .then(function () {
            pushBtn.disabled = false;
            pushBtn.textContent = "🚀 Push to target key";
          });
      };
    }
    var slot = document.getElementById("_aur_form_slot");
    if (slot) {
      slot.addEventListener("input", updatePreview, true);
      slot.addEventListener("change", updatePreview, true);
    }
  }

  function _doQuickClone(source, target, bonusN) {
    source = _normKey(source);
    target = _normKey(target);
    bonusN = Math.max(0, Number(bonusN) || 0);
    if (!source) { _toast("Enter a source userKey to copy FROM", "err"); return; }
    if (!target) { _toast("Enter a target userKey to apply TO", "err"); return; }
    _state.userKey = source;
    _state.targetKey = target;
    _state.statInputs = {};
    _state.trophySelection = {};
    var btn = document.getElementById("_aur_btn_qc");
    if (btn) { btn.disabled = true; btn.textContent = "⏳ Cloning…"; }
    // Reflect normalization back into the visible inputs so the user
    // sees what's actually being fetched / pushed.
    var srcInput = document.getElementById("_aur_input_userkey");
    if (srcInput) srcInput.value = source;
    var qcSrc = document.getElementById("_aur_qc_source");
    if (qcSrc) qcSrc.value = source;
    var qcTgt = document.getElementById("_aur_qc_target");
    if (qcTgt) qcTgt.value = target;
    _loadTrophyCatalog()
      .then(function () { return _ghGetJson("usage/" + source + ".json"); })
      .then(function (digest) {
        if (!digest) {
          _state.loadedDigest = null;
          _state.reconstructed = {
            stats: { totalActiveDays: 0, docsReviewed: 0, draftsCreated: 0, errorsFixed: 0, risksFound: 0, hoursSaved: 0, currentStreak: 0 },
            trophyIds: [], trophyDates: {}, source: "empty",
          };
          _toast("Source " + source + " has no telemetry file — cloning zeros. Add trophies + edit fields manually.", "warn");
        } else {
          _state.loadedDigest = digest;
          _state.reconstructed = _reduceDigest(digest);
        }
        document.getElementById("_aur_preview_slot").innerHTML = _renderPreview(_state.reconstructed);
        document.getElementById("_aur_form_slot").innerHTML = _renderForm(_state.reconstructed);
        document.getElementById("_aur_export_slot").innerHTML = _renderExport();
        _wireForm();
        _wireExport();
        _updateTrophyCount();
        if (bonusN > 0) _awardNEasiest(bonusN); // re-renders + refreshes on its own
        _toast("✅ Cloned " + source + " → " + target +
          (bonusN > 0 ? " + " + bonusN + " bonus trophies" : "") +
          ". Review below, then click 🚀 Push.", "ok");
      })
      .catch(function (err) {
        _toast("Clone failed: " + (err && err.message || "unknown"), "err");
      })
      .then(function () {
        if (btn) { btn.disabled = false; btn.textContent = "🧬 Clone + bonus"; }
      });
  }

  function _wireQuickClone() {
    var btn = document.getElementById("_aur_btn_qc");
    if (!btn) return;
    btn.onclick = function () {
      var s = document.getElementById("_aur_qc_source");
      var t = document.getElementById("_aur_qc_target");
      var b = document.getElementById("_aur_qc_bonus");
      _doQuickClone(s ? s.value : "", t ? t.value : "", b ? b.value : 0);
    };
  }

  function _launch() {
    var out = window.eli.ui && typeof window.eli.ui.claimOutput === "function"
      ? window.eli.ui.claimOutput()
      : document.getElementById("output");
    if (!out) return;
    out.classList.add("eli-view-enter");
    out.innerHTML = _renderRoot();
    _wireQuickClone();
    _wirePreview();
  }

  if (eli.register) {
    eli.register({
      tile: {
        app_admin_user_restore: eli.events && eli.events.guard
          ? eli.events.guard(function () { _launch(); }, "admin_user_restore.tile")
          : function () { _launch(); },
      },
    });
  }

  if (eli.log && eli.log.event) eli.log.event("tool", "admin_user_restore_initialized", {});
}

jsonTools.css:
/* Admin User Restore — layout only, matches ELI admin-tool grammar
   (light card, navy accents, squared corners, no drop shadows). */

._aur_root {
  font-family: Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0;
  min-height: 100%;
  flex: 1 0 auto;
}

._aur_header {
  background: linear-gradient(120deg, #12346f, #1d4a94 44%, #3b82f6);
  color: #fff;
  padding: 14px 18px;
  border-bottom: 1px solid #1e3a8a;
}
._aur_title {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.02em;
}
._aur_subtitle {
  font-size: 11px;
  font-weight: 500;
  color: #dbeafe;
  margin-top: 3px;
  letter-spacing: 0.03em;
}

._aur_body {
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

._aur_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 0;
  padding: 12px 14px;
}
._aur_card_hero {
  background: linear-gradient(135deg, #f0f9ff, #ecfdf5);
  border-left: 4px solid #16a34a;
}
._aur_qc_grid {
  display: grid;
  grid-template-columns: 1fr 1fr 100px auto;
  gap: 8px;
  align-items: end;
  margin-top: 8px;
}
._aur_qc_btn {
  height: 32px;
  align-self: end;
}
@media (max-width: 620px) {
  ._aur_qc_grid { grid-template-columns: 1fr; }
  ._aur_qc_btn { width: 100%; }
}
._aur_card_title {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #1e40af;
  margin-bottom: 8px;
}

._aur_row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
._aur_lbl {
  font-size: 11px;
  font-weight: 700;
  color: #475569;
  min-width: 62px;
}
._aur_inp {
  flex: 1 1 200px;
  padding: 6px 8px;
  font-family: Consolas, "Segoe UI Mono", monospace;
  font-size: 12px;
  border: 1px solid #cbd5e1;
  border-radius: 0;
  background: #fff;
  color: #0f172a;
  min-width: 180px;
}
._aur_inp:focus {
  outline: 2px solid #3b82f6;
  outline-offset: -1px;
}
._aur_inp_num {
  font-family: Inter, sans-serif;
  max-width: 110px;
  min-width: 80px;
}

._aur_btn {
  font-family: Inter, sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  padding: 6px 12px;
  border-radius: 0;
  cursor: pointer;
  border: 1px solid #cbd5e1;
  background: linear-gradient(135deg, #ffffff, #f1f5f9);
  color: #0f172a;
  transition: background 0.12s ease;
}
._aur_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #f1f5f9, #e2e8f0);
}
._aur_btn:disabled { opacity: 0.55; cursor: default; }
._aur_btn_primary {
  background: linear-gradient(135deg, #1d4a94, #12346f);
  border-color: #12346f;
  color: #fff;
}
._aur_btn_primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #12346f, #0b264f);
}
._aur_btn_ghost {
  background: transparent;
  border-color: #cbd5e1;
  color: #475569;
}

._aur_hint {
  font-size: 11px;
  color: #64748b;
  margin-top: 6px;
  line-height: 1.5;
}
._aur_hint code {
  background: #f1f5f9;
  padding: 1px 5px;
  font-family: Consolas, monospace;
  font-size: 10px;
}
._aur_hint_src {
  color: #1e40af;
  font-weight: 600;
}

._aur_stat_grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 6px;
  margin-top: 6px;
}
._aur_stat_chip {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 4px 8px;
  font-size: 11px;
  color: #1e3a8a;
}
._aur_stat_chip b {
  color: #0f172a;
  font-weight: 800;
}
._aur_trophy_bit {
  margin-top: 8px;
  padding: 4px 8px;
  background: #fef3c7;
  border: 1px solid #f59e0b;
  color: #78350f;
  font-size: 11px;
  font-weight: 700;
  display: inline-block;
}

._aur_stat_form {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 8px;
  margin: 10px 0;
}
._aur_fld {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
._aur_fld_lbl {
  font-size: 10px;
  font-weight: 700;
  color: #475569;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

._aur_metric_head {
  margin-top: 14px;
  font-size: 11px;
  font-weight: 800;
  color: #1e40af;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
._aur_metric_sub {
  font-size: 10px;
  font-weight: 500;
  color: #64748b;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 6px;
}
._aur_fld_hint {
  font-size: 9px;
  font-weight: 500;
  color: #94a3b8;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 4px;
}

._aur_trophy_head {
  margin-top: 12px;
  font-size: 11px;
  font-weight: 800;
  color: #0f172a;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
._aur_trophy_bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 6px 0 8px 0;
}
._aur_trophy_count {
  font-size: 11px;
  font-weight: 700;
  color: #1e40af;
  margin-left: auto;
}
._aur_trophy_grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 6px;
  max-height: 340px;
  overflow-y: auto;
  padding: 4px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
._aur_trophy_tile {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  background: #fff;
  border: 1px solid #e2e8f0;
  cursor: pointer;
  font-size: 11px;
  user-select: none;
}
._aur_trophy_tile:hover {
  background: #f1f5f9;
  border-color: #94a3b8;
}
._aur_trophy_on {
  background: #dcfce7;
  border-color: #86efac;
}
._aur_trophy_on:hover {
  background: #bbf7d0;
  border-color: #22c55e;
}
._aur_trophy_cb {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  accent-color: #16a34a;
}
._aur_trophy_icon {
  font-size: 16px;
  flex-shrink: 0;
}
._aur_trophy_text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  flex: 1;
}
._aur_trophy_prog {
  height: 3px;
  background: #e2e8f0;
  margin-top: 4px;
  border-radius: 0;
  overflow: hidden;
}
._aur_trophy_prog_fill {
  height: 100%;
  background: linear-gradient(90deg, #3b82f6, #1d4a94);
  transition: width 0.15s ease;
}
._aur_trophy_prog_label {
  font-family: Consolas, monospace;
  font-size: 9px;
  color: #64748b;
  margin-top: 2px;
  display: block;
}
._aur_trophy_title {
  font-weight: 700;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._aur_trophy_id {
  font-family: Consolas, monospace;
  font-size: 9px;
  color: #94a3b8;
  letter-spacing: 0.02em;
}

._aur_export_row {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}
._aur_preview_pre {
  margin-top: 10px;
  max-height: 200px;
  overflow: auto;
  padding: 8px 10px;
  background: #0f172a;
  color: #cbd5e1;
  font-family: Consolas, monospace;
  font-size: 10px;
  border: 1px solid #1e293b;
  white-space: pre-wrap;
  word-break: break-all;
}
